/**
 * One emoji: the character, its Unicode name, group and subgroup, its shortcodes and tags (gemoji), and the label a
 * list shows (its first shortcode, or its name when it has none).
 */
export type Emoji = { id: string; label: string; char: string; name: string; group: string; subgroup: string; aliases: string[]; tags: string[] }

const words = (s: string) => (s ? s.split(' ') : [])
export const emoji: Emoji[] = DATA.map(([char, name, group, subgroup, aliases, tags]) => {
  const codes = words(aliases)
  return { id: codes[0] ?? name.replace(/ /g, '_'), label: codes[0] ? `:${codes[0]}:` : name, char, name, group: GROUPS[group]!, subgroup: SUBGROUPS[subgroup]!, aliases: codes, tags: words(tags) }
})
